def eval_task(self, agent_responses=None):
    """Check: email sent AND PayPal payment made, with data-grounded content."""
    email_ok = False
    paypal_ok = False
    data_ok = False
    eps_dis = False
    high52w_wbd = False
    headline_dis = False
    try:
        msgs = search_messages(token=self.gmail_token, to_address="nina.petrov@moscowpw.com")
        email_ok = len(msgs) > 0
        if email_ok:
            body = ""
            for m in msgs:
                body += get_message_body(token=self.gmail_token, message_id=(m.get("ID") or m.get("id") or "")).lower()
            eps_dis = "2.46" in body
            high52w_wbd = "30.0" in body or "30.00" in body
            headline_dis = "zootopia" in body or "disney" in body
            data_ok = eps_dis and high52w_wbd and headline_dis
    except Exception:
        pass
    try:
        payouts = list_payouts(access_token=self.paypal_token) or []
        for p in payouts:
            if p.get("receiver_email", "").lower() == "marketing@firm14.com":
                paypal_ok = True
    except Exception:
        pass
    ok = email_ok and paypal_ok and data_ok
    return ok, {"email_sent": email_ok, "paypal_sent": paypal_ok, "data_ok": data_ok, "eps_dis": eps_dis, "high52w_wbd": high52w_wbd, "headline_dis": headline_dis}
